mapper.select:
select
from gc_master m
left join gc_manager man on man.master_id=m.id where m.manager_id=#{uid} or man.id =#{uid}

select
m.id , m.org_name, m.logo_id,m.portal_name

from gc_master m

where gcSubject.type = ${@com.threeatom.guidecore.constant.TableConstant@gcSubject_type_subject0}
and gcSubject.is_public = ${@com.threeatom.guidecore.constant.TableConstant@gcSubject_isPublic_1}
and gcSubject.state !=${@com.threeatom.guidecore.constant.TableConstant@gcSubject_state_hidden_0}

mapper.update:
UPDATE gc_master
SET intro_video_id = NULL
WHERE id = #{id}

UPDATE gc_master
SET source_type = NULL, source_url=NULL
WHERE id = #{id}

update gc_master
set email_cc = #{email,typeHandler=com.threeatom.common.mybatis.typehandler.FastJsonArrayTypeHandler}
where id = #{id}

mapper.select:
select
from gc_master m
where m.context=#{context}

select m.*
from gc_master m
where m.id=#{id}

select m.*,a.id as accessId,a.code as accessCode from gc_master m left join gc_access a on a.master_id = m.id where m.id in
#{masterId}
group by m.id,a.id

select
m.id , m.org_name, m.logo_id,m.portal_name,
concat('[',GROUP_CONCAT('"',tags.tag_text,'"' SEPARATOR ','),']') as course_tags

from gc_master m

left join gc_subject_tags tags on tags.subject_id = gcSubject.id and tags.master_id = m.id and tags.`status` = 0 and tags.type = 1
where gcSubject.type = ${@com.threeatom.guidecore.constant.TableConstant@gcSubject_type_subject0}
and gcSubject.is_public = ${@com.threeatom.guidecore.constant.TableConstant@gcSubject_isPublic_1}
and gcSubject.state !=${@com.threeatom.guidecore.constant.TableConstant@gcSubject_state_hidden_0}

	and m.id = #{masterId}


	and tags.tag_text = #{tag}

GROUP BY gcSubject.id

select a.code,a.id as accessId,m.id as managerId,m.last_name,m.first_name,m.level,m.master_id,m.create_time as dateSignedUp,m.username as email,a.lastLoginTime as lastLoginTime from gc_master ma LEFT JOIN gc_manager m on m.master_id = ma.id LEFT JOIN gc_user_access ac on ac.master_id = m.master_id and ac.manager_id=m.id LEFT JOIN gc_access a on a.id = ac.access_id left join (select max(log_in_time) as lastLoginTime,manager_id,user_access_id from gc_user_access_ext group by manager_id)a on m.id = a.manager_id where m.level=1
and m.master_id = #{masterId}
and concat_ws(',',m.last_name,m.first_name,m.username,a.code) like concat('%',#{searchFilter},'%')
